bool before(const CommonStore& c,const StableId& a,const StableId& b){const auto& order=c.state().facts.order();const auto x=std::find(order.begin(),order.end(),a),y=std::find(order.begin(),order.end(),b);return x!=order.end()&&y!=order.end()&&x<y;}
bool header(const CommonStore& c,const StableId& id,const StableId& prefix,const StableId& kind,const StableId& domain){const auto n=organization_instance_sequence(id,prefix);const auto* fact=c.state().facts.find(id);return n&&*n<c.state().next_instance_id&&fact&&fact->id==id&&fact->kind==kind&&fact->domain==domain;}
